head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > setDisabled]<br/>지정한 컴포넌트와 하위의 모든 컴포넌트들의 비활성화(disabled) 상태를 설정합니다.",
    "validation" : [
        "info(필수) 파라미터로 비활성화(disabled) 처리 옵션을 JSON 객체로 설정할 수 있어야 합니다.",
        "info.componentId(선택) 파라미터로 대상 컴포넌트의 ID 를 설정할 수 있어야 합니다.",
        "info.componentId(선택) 파라미터값이 빈 문자열(Empty String) 이거나 설정하지 않으면 현재 페이지의 Body 요소에 속한 모든 컴포넌트를 대상으로 해야 합니다.",
        "info.componentId(선택) 파라미터값에 해당하는 컴포넌트를 찾지 못하면 로그를 출력하고 빈 결과를 반환해야 합니다.",
        "info.disabled(필수) 파라미터를 true 로 설정하면 대상 컴포넌트와 하위의 모든 컴포넌트들을 비활성화(disabled) 상태로 설정해야 합니다.",
        "info.disabled(필수) 파라미터를 false 로 설정하면 대상 컴포넌트와 하위의 모든 컴포넌트들을 활성화(enabled) 상태로 설정해야 합니다.",
        "info.excludeIdList(선택) 파라미터로 비활성화(disabled) 상태 설정에서 제외할 컴포넌트의 ID 목록을 배열로 설정할 수 있어야 합니다.",
        "info.includeIdList(선택) 파라미터로 비활성화(disabled) 상태를 설정할 컴포넌트의 ID 목록을 배열로 설정할 수 있어야 합니다.",
        "info.includeIdList(선택) 파라미터를 설정하면 해당 목록의 컴포넌트만 처리되며, 나머지 컴포넌트는 영향받지 않아야 합니다.",
        "info.includeIdList 속성과 info.excludeIdList 속성이 모두 설정되어 있으면, info.includeIdList 속성이 먼저 적용된 후 info.excludeIdList 속성이 적용되어야 합니다.",
        "result.doneComponents 에 비활성화(disabled) 상태를 변경한 컴포넌트의 렌더링 ID 를 배열로 반환해야 합니다.",
        "result.skipComponents 에 이미 해당 상태여서 건너뛴 컴포넌트의 렌더링 ID 를 배열로 반환해야 합니다.",
    ]
}



// comp 생성
scwin.comp_init = async function () {
    if (typeof grp_target !== 'undefined') {
        grp_target.remove();
    }

    var ns = $c.gcm.getNameSpace();
    var grp_comp = $c.gcm.getTestGroup();

    var strGrp = '<xf:group ' + ns + ' id="grp_target" style="padding:10px; border:1px solid #ccc;"></xf:group>';
    await $p.dynamicCreate('grp_target', 'group', strGrp, grp_comp);

    var strInput1 = '<xf:input ' + ns + ' id="target_input1" style="width:150px;" placeholder="target_input1"></xf:input>';
    await $p.dynamicCreate('target_input1', 'input', strInput1, grp_target);

    var strInput2 = '<xf:input ' + ns + ' id="target_input2" style="width:150px;" placeholder="target_input2"></xf:input>';
    await $p.dynamicCreate('target_input2', 'input', strInput2, grp_target);

    var strBtn = '<w2:button ' + ns + ' class="tc_btn_basic" id="target_btn1" label="target_btn1" style=""></w2:button>';
    await $p.dynamicCreate('target_btn1', 'button', strBtn, grp_target);

    var strSelect = '<xf:select1 ' + ns + ' appearance="minimal" id="target_select1" style="width:150px;">'
        + '<xf:choices><xf:item><xf:label>항목1</xf:label><xf:value>1</xf:value></xf:item>'
        + '<xf:item><xf:label>항목2</xf:label><xf:value>2</xf:value></xf:item></xf:choices>'
        + '</xf:select1>';
    await $p.dynamicCreate('target_select1', 'selectbox', strSelect, grp_target);

    var strCheckbox = '<w2:checkbox ' + ns + ' id="target_checkbox1" label="target_checkbox1" style=""></w2:checkbox>';
    await $p.dynamicCreate('target_checkbox1', 'checkbox', strCheckbox, grp_target);

    var strTextarea = '<xf:textarea ' + ns + ' id="target_textarea1" style="width:150px; height:50px;" placeholder="target_textarea1"></xf:textarea>';
    await $p.dynamicCreate('target_textarea1', 'textarea', strTextarea, grp_target);
}



scwin.onpageload = async function () {
    $c.gcm.createCommonDatalist();
    await scwin.comp_init();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_setDisabled_onclick = function () {
    var componentId = par_componentId.getValue();
    var disabled = par_disabled.getText() === "true";
    var excludeIdList = par_excludeIdList.getValue();
    var includeIdList = par_includeIdList.getValue();
    var info = {disabled: disabled};

    if (componentId !== "미설정") {
        info.componentId = componentId;
    }

    if (excludeIdList !== "미설정") {
        info.excludeIdList = JSON.parse(excludeIdList);
    }

    if (includeIdList !== "미설정") {
        info.includeIdList = JSON.parse(includeIdList);
    }

    wf_body_bottom.getObj("scwin").setReturnValue("info : " + JSON.stringify(info));

    var result = $p.setDisabled(info);

    wf_body_bottom.getObj("scwin").setReturnValue("result.doneComponents : " + JSON.stringify(result.doneComponents));
    wf_body_bottom.getObj("scwin").setReturnValue("result.skipComponents : " + JSON.stringify(result.skipComponents));

    var compIds = ["target_input1", "target_input2", "target_btn1", "target_select1", "target_checkbox1", "target_textarea1"];
    var states = [];
    for (var i = 0; i < compIds.length; i++) {
        var comp = $p.getComponentById(compIds[i]);
        if (comp) {
            states.push(compIds[i] + "=" + comp.getDisabled());
        }
    }
    wf_body_bottom.getObj("scwin").setReturnValue("disabled 상태 : " + states.join(", "));
}
